const revokeActiveDelegationsOfActor = `-- name: RevokeActiveDelegationsOfActor :many
UPDATE delegation.delegated_operation_sessions
SET status = 'revoked',
    revoked_at = date_trunc('second', $1::timestamptz),
    ended_at = LEAST(expires_at, date_trunc('second', $1::timestamptz)),
    revoke_reason = $2::text,
    revoked_by_admin_id = $3::bigint,
    revision = revision + 1,
    updated_at = $1::timestamptz
WHERE actor_admin_id = $4
  AND status = 'active' AND ended_at IS NULL
  AND $1::timestamptz < expires_at
  AND last_active_at > $5::timestamptz
RETURNING id
`

type RevokeActiveDelegationsOfActorParams struct {
	Now              time.Time
	RevokeReason     string
	RevokedByAdminID *int64
	ActorAdminID     int64
	IdleSince        time.Time
}

// revoked_by_admin_id 可為 NULL：系統因角色變動而撤銷時沒有操作者，不填被撤銷者自己。
func (q *Queries) RevokeActiveDelegationsOfActor(ctx context.Context, arg RevokeActiveDelegationsOfActorParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, revokeActiveDelegationsOfActor,
		arg.Now,
		arg.RevokeReason,
		arg.RevokedByAdminID,
		arg.ActorAdminID,
		arg.IdleSince,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

