const revokeDelegationSession = `-- name: RevokeDelegationSession :one
UPDATE delegation.delegated_operation_sessions
SET status = 'revoked',
    revoked_at = date_trunc('second', $1::timestamptz),
    ended_at = COALESCE(ended_at, LEAST(expires_at, date_trunc('second', $1::timestamptz))),
    revoke_reason = $2::text,
    revoked_by_admin_id = $3::bigint,
    revision = revision + 1,
    updated_at = $1::timestamptz
WHERE id = $4 AND revoked_at IS NULL
  AND (NOT $5::boolean OR (
    status = 'active' AND ended_at IS NULL
    AND $1::timestamptz < expires_at
    AND last_active_at > $6::timestamptz
  ))
RETURNING id, display_code, credential_hash, handoff_code_hash, handoff_expires_at, actor_admin_id, actor_display_name, target_store_id, target_seller_account_id, target_store_name, reason_code, reason_label, case_reference, capabilities, issued_at, expires_at, last_active_at, ended_at, revoked_at, revoked_by_admin_id, revoke_reason, status, revision, idempotency_key, create_request_id, create_correlation_id, create_user_agent, created_at, updated_at
`

type RevokeDelegationSessionParams struct {
	Now              time.Time
	RevokeReason     string
	RevokedByAdminID int64
	ID               int64
	OnlyActive       bool
	IdleSince        time.Time
}

// 治理的撤銷：單句 CAS；單筆撤銷只要求 revoked_at IS NULL（已到期或已結束的也能撤銷，留下治理痕跡）。沒有列表示已經
// 撤銷過，呼叫方回傳既有的列（revoked_at 是舉證欄，不能每次不同）。ended_at 一起寫：已經結束的保留原本的時刻，
// 已經到期的取 expires_at，否則摘要的時長會隨查詢時刻長大。only_active 用於撤回授權與管理員登出，
// 只撤銷仍符合四項進行中述詞的列；治理的單筆撤銷不設此限制。
func (q *Queries) RevokeDelegationSession(ctx context.Context, arg RevokeDelegationSessionParams) (DelegationDelegatedOperationSession, error) {
	row := q.db.QueryRow(ctx, revokeDelegationSession,
		arg.Now,
		arg.RevokeReason,
		arg.RevokedByAdminID,
		arg.ID,
		arg.OnlyActive,
		arg.IdleSince,
	)
	var i DelegationDelegatedOperationSession
	err := row.Scan(
		&i.ID,
		&i.DisplayCode,
		&i.CredentialHash,
		&i.HandoffCodeHash,
		&i.HandoffExpiresAt,
		&i.ActorAdminID,
		&i.ActorDisplayName,
		&i.TargetStoreID,
		&i.TargetSellerAccountID,
		&i.TargetStoreName,
		&i.ReasonCode,
		&i.ReasonLabel,
		&i.CaseReference,
		&i.Capabilities,
		&i.IssuedAt,
		&i.ExpiresAt,
		&i.LastActiveAt,
		&i.EndedAt,
		&i.RevokedAt,
		&i.RevokedByAdminID,
		&i.RevokeReason,
		&i.Status,
		&i.Revision,
		&i.IdempotencyKey,
		&i.CreateRequestID,
		&i.CreateCorrelationID,
		&i.CreateUserAgent,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const touchDelegationSession = `-- name: TouchDelegationSession :one
UPDATE delegation.delegated_operation_sessions
SET last_active_at = CASE
        WHEN status = 'active' AND ended_at IS NULL
             AND $1::timestamptz < expires_at
             AND last_active_at > $2::timestamptz
        THEN date_trunc('second', $1::timestamptz)
        ELSE last_active_at
    END
WHERE credential_hash = $3
RETURNING id, display_code, credential_hash, handoff_code_hash, handoff_expires_at, actor_admin_id, actor_display_name, target_store_id, target_seller_account_id, target_store_name, reason_code, reason_label, case_reference, capabilities, issued_at, expires_at, last_active_at, ended_at, revoked_at, revoked_by_admin_id, revoke_reason, status, revision, idempotency_key, create_request_id, create_correlation_id, create_user_agent, created_at, updated_at
`

type TouchDelegationSessionParams struct {
	Now            time.Time
	IdleSince      time.Time
	CredentialHash []byte
}

// 代行資源路由的 credential 反查，同一句順延閒置逾時。只動 last_active_at（動 revision 會讓前端對帳失敗，動
// expires_at 就是 sliding expiration）。條件放在 CASE 裡而不是 WHERE：終態的 session 也要回傳，呼叫方才回得出
// expired、revoked；條件要含閒置與 hard 到期，否則下一個請求會把已經逾時的 session 救回來。
func (q *Queries) TouchDelegationSession(ctx context.Context, arg TouchDelegationSessionParams) (DelegationDelegatedOperationSession, error) {
	row := q.db.QueryRow(ctx, touchDelegationSession, arg.Now, arg.IdleSince, arg.CredentialHash)
	var i DelegationDelegatedOperationSession
	err := row.Scan(
		&i.ID,
		&i.DisplayCode,
		&i.CredentialHash,
		&i.HandoffCodeHash,
		&i.HandoffExpiresAt,
		&i.ActorAdminID,
		&i.ActorDisplayName,
		&i.TargetStoreID,
		&i.TargetSellerAccountID,
		&i.TargetStoreName,
		&i.ReasonCode,
		&i.ReasonLabel,
		&i.CaseReference,
		&i.Capabilities,
		&i.IssuedAt,
		&i.ExpiresAt,
		&i.LastActiveAt,
		&i.EndedAt,
		&i.RevokedAt,
		&i.RevokedByAdminID,
		&i.RevokeReason,
		&i.Status,
		&i.Revision,
		&i.IdempotencyKey,
		&i.CreateRequestID,
		&i.CreateCorrelationID,
		&i.CreateUserAgent,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
